fun main() {
    // 1) Basit değer eşleştirme
    val x = 2
    when (x) {
        1 -> println("Bir")
        2, 3 -> println("Kiçik rəqəm: $x")   // birden fazla değer virgülle
        else -> println("Digər")
    }

    // 2) İfade olarak + aralık
    val gun = 3
    val tip = when (gun) {
        in 1..5 -> "İş günü"
        6, 7 -> "İstirahət"
        else -> "Yanlış gün"
    }
    println(tip)

    // 3) Tür kontrolü (is) — smart cast çalışır
    val obyekt: Any = 42
    when (obyekt) {
        is Int -> println("Rəqəm")
        is String -> println("Uzunluq: ${obyekt.length}")  // otomatik String
        is List<*> -> println("Siyahı, ${obyekt.size} element")
        else -> println("Naməlum tip")
    }

    // 4) Argümansız when — if-else zincirinin yerini alır
    val temperatur = 5
    val geyim = when {
        temperatur < 0 -> "Qalın palto"
        temperatur in 1..10 -> "1-dən 10-a qədər"
        temperatur in 11..20 -> "Yüngül gödəkçə"
        else -> "Köynək"
    }
    println(geyim)

    // 5) when sonucunu doğrudan döndürmek
    println(olcuAdi(150))
}

