fun main() {
    // break — döngüyü tamamen durdurur
    for (i in 1..5) {
        if (i == 3) break
        print("$i ")
    }
    println()

    // continue — mevcut adımı atlar
    for (i in 1..5) {
        if (i % 2 == 0) continue
        print("$i ")
    }
    println()

    // Etiket — iç içe döngülerden çıkmak için
    xarici@ for (i in 1..3) {
        for (j in 1..3) {
            if (i * j == 2) {
                println("Tapıldı: ($i, $j)")
                break@xarici     // her iki döngüden çıkar
            }
        }
    }
}

