inline fun <T> olcuVaxt(blok: () -> T): T {
    val basla = System.currentTimeMillis()
    val netice = blok()
    println("Əməliyyat ${System.currentTimeMillis() - basla} ms çəkdi")
    return netice
}

// 2) Kendi map fonksiyonumuz
fun <T, R> List<T>.menimMap(cevir: (T) -> R): List<R> {
    val netice = mutableListOf<R>()
    for (element in this) netice.add(cevir(element))
    return netice
}

// 3) Fonksiyon DÖNDÜREN fonksiyon
fun vurucuYarat(k: Int): (Int) -> Int = { it * k }

