data class Istifadeci(val id: Long, val ad: String, val email: String)

@RestController
@RequestMapping("/api/istifadeciler")
class IstifadeciController(private val servis: IstifadeciServisi) {

    @GetMapping
    fun hamisi(): List<Istifadeci> = servis.hamisi()

    @GetMapping("/{id}")
    fun tap(@PathVariable id: Long): ResponseEntity<Istifadeci> =
        servis.tap(id)
            ?.let { ResponseEntity.ok(it) }
            ?: ResponseEntity.notFound().build()

    // Spring WebFlux ile suspend fonksiyonlar doğrudan desteklenir
    @PostMapping
    suspend fun yarat(@RequestBody istifadeci: Istifadeci): Istifadeci =
        servis.yarat(istifadeci)
}

import org.jetbrains.exposed.sql.*
import org.jetbrains.exposed.sql.transactions.transaction

object Istifadeciler : Table("istifadeciler") {
    val id = integer("id").autoIncrement()
    val ad = varchar("ad", 100)
    val email = varchar("email", 200).uniqueIndex()
    val yas = integer("yas").nullable()

    override val primaryKey = PrimaryKey(id)
}

fun main() {
    Database.connect("jdbc:postgresql://localhost:5432/baza",
        driver = "org.postgresql.Driver", user = "admin", password = "sirr")

    transaction {
        SchemaUtils.create(Istifadeciler)

        // INSERT
        Istifadeciler.insert {
            it[ad] = "Aysel"
            it[email] = "aysel@mail.az"
            it[yas] = 24
        }

        // SELECT — tür güvenli DSL
        val boyukler = Istifadeciler
            .select { Istifadeciler.yas greaterEq 18 }
            .orderBy(Istifadeciler.ad)
            .map { it[Istifadeciler.ad] }

        // UPDATE
        Istifadeciler.update({ Istifadeciler.ad eq "Aysel" }) {
            it[yas] = 25
        }
    }
}

import kotlin.test.*

class HesablayiciTest {

    private lateinit var hesablayici: Hesablayici

    @BeforeTest
    fun hazirla() {
        hesablayici = Hesablayici()
    }

    // Test adları backtick içinde — belge gibi okunur
    @Test
    fun `iki musbet reqemi toplayir`() {
        assertEquals(5, hesablayici.topla(2, 3))
    }

    @Test
    fun `sifira bolende istisna atir`() {
        val xeta = assertFailsWith<ArithmeticException> {
            hesablayici.bol(10, 0)
        }
        assertEquals("Sıfıra bölmək olmaz", xeta.message)
    }

    @Test
    fun `bos siyahi ucun null qaytarir`() {
        assertNull(emptyList<Int>().maxOrNull())
    }

    @Test
    fun `siyahida element var`() {
        val netice = listOf(1, 2, 3)
        assertTrue(netice.contains(2))
        assertContentEquals(listOf(1, 2, 3), netice)
    }
}

import kotlinx.coroutines.test.*
import kotlin.test.*

class RepoTest {

    // runTest — delay'leri sanal zamanla anında geçer
    @Test
    fun `melumat ugurla yuklenir`() = runTest {
        val repo = IstifadeciRepo(SaxtaApi())

        val netice = repo.hamisiniGetir()   // içindeki delay(5000) anında geçer

        assertEquals(2, netice.size)
        assertEquals("Aysel", netice.first().ad)
    }

    @Test
    fun `sebeke xetasi duzgun idare olunur`() = runTest {
        val repo = IstifadeciRepo(XetaliApi())

        assertFailsWith<NetworkException> {
            repo.hamisiniGetir()
        }
    }
}

import io.mockk.*
import kotlin.test.*

class ServisTest {

    private val repo = mockk<IstifadeciRepo>()
    private val servis = IstifadeciServisi(repo)

    @Test
    fun `repodan gelen melumat cevrilir`() {
        // Hazırlık
        every { repo.tap(1) } returns Istifadeci(1, "Aysel")

        // Çalıştırma
        val netice = servis.adiAl(1)

        // Doğrulama
        assertEquals("Aysel", netice)
        verify(exactly = 1) { repo.tap(1) }
    }

    @Test
    fun `suspend funksiya mock-lanir`() = runTest {
        coEvery { repo.hamisiniGetir() } returns listOf(Istifadeci(1, "Aysel"))

        val netice = servis.hamisi()

        assertEquals(1, netice.size)
        coVerify { repo.hamisiniGetir() }
    }
}

